select json_build_object(
  'conta', coalesce((select json_build_object('id',u.id,'email',u.email,'created_at',u.created_at) from auth.users u where u.id='3204787f-3736-43e7-b940-c1facf6da17c'), 'null'::json),
  'perfil', (select to_jsonb(p) from profiles p where p.id='3204787f-3736-43e7-b940-c1facf6da17c'),
  'turma', (select to_jsonb(c) from classes c where c.id='dfee8520-a361-45e9-b5dc-25c5684df41b'),
  'alunos', coalesce((select json_agg(to_jsonb(s)) from students s where s.id in ('a05e54a9-724d-449d-8894-cc904ed421e0','e8faf66b-920a-4acb-88ec-241dba7291e1')), '[]'::json),
  'vinculo', coalesce((select json_agg(json_build_object('id',t.id,'profile_id',t.profile_id,'class_id',t.class_id,'subject',t.subject,'active',t.active)) from bfr_teacher_class_subjects t where t.profile_id='3204787f-3736-43e7-b940-c1facf6da17c'), '[]'::json),
  'notas', coalesce((select json_agg(json_build_object('id',g.id,'student_id',g.student_id,'subject',g.subject,'assessment',g.assessment,'category',g.category,'score',g.score,'term',g.term,'entered_by',g.entered_by)) from grades g where g.student_id in ('a05e54a9-724d-449d-8894-cc904ed421e0','e8faf66b-920a-4acb-88ec-241dba7291e1')), '[]'::json),
  'auditoria_nota', coalesce((select json_agg(json_build_object('id',a.id,'grade_id',a.grade_id,'old_score',a.old_score,'new_score',a.new_score,'reason',a.reason,'changed_by',a.changed_by)) from bfr_grade_audit a where a.grade_id in (select id from grades where student_id in ('a05e54a9-724d-449d-8894-cc904ed421e0','e8faf66b-920a-4acb-88ec-241dba7291e1'))), '[]'::json),
  'conteudo', coalesce((select json_agg(json_build_object('id',t.id,'class_id',t.class_id,'subject',t.subject,'lesson_date',t.lesson_date,'profile_id',t.profile_id)) from bfr_teacher_content t where t.class_id='dfee8520-a361-45e9-b5dc-25c5684df41b'), '[]'::json),
  'diario', coalesce((select json_agg(json_build_object('id',t.id,'class_id',t.class_id,'subject',t.subject,'lesson_date',t.lesson_date,'profile_id',t.profile_id)) from bfr_teacher_diary t where t.class_id='dfee8520-a361-45e9-b5dc-25c5684df41b'), '[]'::json),
  'planejamento', coalesce((select json_agg(json_build_object('id',t.id,'class_id',t.class_id,'subject',t.subject,'period',t.period,'profile_id',t.profile_id)) from bfr_teacher_plans t where t.class_id='dfee8520-a361-45e9-b5dc-25c5684df41b'), '[]'::json),
  'leitura', coalesce((select json_agg(json_build_object('student_id',r.student_id,'level',r.level,'note',r.note,'updated_by',r.updated_by)) from student_reading_levels r where r.student_id in ('a05e54a9-724d-449d-8894-cc904ed421e0','e8faf66b-920a-4acb-88ec-241dba7291e1')), '[]'::json),
  'recados', coalesce((select json_agg(x) from (select m.id, m.student_id, m.sender_id, m.recipient_id, m.body, m.created_at from student_messages m where m.student_id in ('a05e54a9-724d-449d-8894-cc904ed421e0','e8faf66b-920a-4acb-88ec-241dba7291e1') order by m.created_at) x), '[]'::json),
  'atividades', coalesce((select json_agg(json_build_object('id',a.id,'class_id',a.class_id,'title',a.title)) from school_activities a where a.class_id='dfee8520-a361-45e9-b5dc-25c5684df41b'), '[]'::json),
  'frequencia', coalesce((select json_agg(to_jsonb(a)) from attendance a where a.student_id in ('a05e54a9-724d-449d-8894-cc904ed421e0','e8faf66b-920a-4acb-88ec-241dba7291e1')), '[]'::json),
  'contagens', json_build_object(
    'grades', (select count(*) from grades),
    'attendance', (select count(*) from attendance),
    'bfr_lesson_attendance', (select count(*) from bfr_lesson_attendance),
    'bfr_lesson_attendance_audit', (select count(*) from bfr_lesson_attendance_audit),
    'school_activities', (select count(*) from school_activities),
    'learning_action_plans', (select count(*) from learning_action_plans),
    'student_messages', (select count(*) from student_messages),
    'student_reading_levels', (select count(*) from student_reading_levels),
    'school_documents', (select count(*) from school_documents),
    'bfr_teacher_content', (select count(*) from bfr_teacher_content),
    'bfr_teacher_diary', (select count(*) from bfr_teacher_diary),
    'bfr_teacher_plans', (select count(*) from bfr_teacher_plans),
    'bfr_teacher_events', (select count(*) from bfr_teacher_events),
    'internal_chat_threads', (select count(*) from internal_chat_threads),
    'internal_chat_messages', (select count(*) from internal_chat_messages),
    'internal_chat_room_members', (select count(*) from internal_chat_room_members),
    'classes', (select count(*) from classes),
    'students', (select count(*) from students),
    'bfr_teacher_class_subjects', (select count(*) from bfr_teacher_class_subjects),
    'auth_users_sinteticos', (select count(*) from auth.users where email like '%@bfr-conecta.test')
  )
) as dados;
